    raise SystemExit('context call snippet not found')
s=s.replace(old,new,1)
anchor='''    private static Context systemContext() throws Exception {
'''
helper='''    private static Context shellContext() throws Exception {
        Context system = systemContext();
        return system.createPackageContext("com.android.shell", Context.CONTEXT_IGNORE_SECURITY);
    }

'''
if helper.strip() not in s:
    if anchor not in s:
        raise SystemExit('systemContext anchor not found')
    s=s.replace(anchor,helper+anchor,1)
